from fastapi import APIRouter, Depends
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.future import select
from sqlalchemy import func
from backend.app.db.session import get_db
from backend.app.db.models import User, GeneratedContent, UsageLog
from backend.app.api.deps import get_current_user

router = APIRouter(prefix="/usage", tags=["usage"])

@router.get("")
async def get_usage_metrics(
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db)
):
    # Total contents generated by user
    total_contents_res = await db.execute(
        select(func.count(GeneratedContent.id)).where(GeneratedContent.user_id == current_user.id)
    )
    total_contents = total_contents_res.scalar() or 0

    # Total image generations / actions
    total_actions_res = await db.execute(
        select(func.count(UsageLog.id)).where(UsageLog.user_id == current_user.id)
    )
    total_actions = total_actions_res.scalar() or 0

    # Industry distribution
    industry_res = await db.execute(
        select(GeneratedContent.industry, func.count(GeneratedContent.id))
        .where(GeneratedContent.user_id == current_user.id)
        .group_by(GeneratedContent.industry)
    )
    industry_breakdown = {row[0]: row[1] for row in industry_res.all()}

    # Language distribution
    lang_res = await db.execute(
        select(GeneratedContent.language, func.count(GeneratedContent.id))
        .where(GeneratedContent.user_id == current_user.id)
        .group_by(GeneratedContent.language)
    )
    language_breakdown = {row[0]: row[1] for row in lang_res.all()}

    return {
        "user_id": current_user.id,
        "email": current_user.email,
        "plan": "Business Pro Plan (Unlimited)",
        "total_generations": total_contents,
        "monthly_limit": 500,
        "remaining_credits": max(0, 500 - total_contents),
        "total_actions": total_actions,
        "industry_breakdown": industry_breakdown,
        "language_breakdown": language_breakdown
    }
